                dataType : "json",
                contentType: "application/json",
                data : JSON.stringify(API_PARAM.INPUT),
                async: (API_PARAM.APIID == 'ZSVC_CHECK_IN_OUT_WTY_RFC' || API_PARAM.APIID == 'Z_CSC_PROD_SAVE' || API_PARAM.APIID == 'Z_CSC_FILE_CONTS' || API_PARAM.APIID == 'ZGW_PS_LAST_TR') ? true : false,
