(() => {
  const $q = window.sg.common.$q;
  const utils = window.sg.common.utils;

  class MyProductListFull extends window.sg.components.Base {
    _init() {
      this.els = {
        el: $q(this.el),
        window: $q(window),
        document: $q(document),
      };
      this.isPc = utils.getCurrentDevice() === 'desktop';
      this.timer = 0;
      this.handler = {
        click: (e) => {
          const target = $q(e.target);
          if (target.closest('.info-tooltip-btn, .warranty-tooltip-btn').target.length) {
            this.handler.showTooltip(e);
            return;
          }
          if (target.closest('.close-btn').target.length) {
            this.handler.hideTooltip(e);
            return;
          }
          if (target.closest('.myd17-my-product-list-full__item-view-more').target.length) {
            this.handler.toggleViewMore(e);
            return;
          }
          if (target.closest('.myd17-my-product-list-full__recommended-tab a').target.length) {
            this.handler.changeTab(e);
            return;
          }
          if (target.closest('.recommended-close-btn').target.length) {
            this.handler.closeRecommended(e);
          }
        },
        keydown: (e) => {
          if (!this.isPc) {
            const target = $q(e.target);
            if (target.closest('.myd17-my-product-list-full__recommended-wrap').target.length) {
              if (target.closest('.recommended-close-btn').target.length) {
                this.handler.popupCloseKeydown(e);
              } else {
                this.handler.popupKeydown(e);
              }
            }
          }
        },
        resize: () => {
          const isPc = utils.getCurrentDevice() === 'desktop';
          if (this.isPc !== isPc) {
            this.isPc = isPc;
            this.els.el.find('.tooltip').target.forEach((el) => {
              if ($q(el).css('display') === 'block') {
                this._toggleTooltip(false, el);
              }
            });
            this.els.el.find('.myd17-my-product-list-full__recommended-wrap').target.forEach((el) => {
              if ($q(el).css('display') === 'block') {
                this._closeRecommended({ target: $q(el).find('.recommended-close-btn').target[0] });
              }
            });
          }
          clearTimeout(this.timer);
          this.timer = setTimeout(() => {
            this.adjustPriceWrapHeight();
          }, 240);
        },
        popupKeydown: (e) => {
          const target = $q(e.target);
          const popupWrap = target.closest('.myd17-my-product-list-full__recommended-wrap');
          const closeButton = target.closest('.myd17-my-product-list-full__recommended-wrap').find('.recommended-close-btn');
          const firstFocusableEl = utils.getFirstFocusableEl(popupWrap.target[0]);
          if (window.sg.common.constants.KEY_CODE.TAB === e.keyCode) {
            if (e.shiftKey && firstFocusableEl && e.target === firstFocusableEl) {
              e.preventDefault();
              closeButton.focus();
            }
          }
        },
        popupCloseKeydown: (e) => {
          const target = $q(e.target);
          const popupWrap = target.closest('.myd17-my-product-list-full__recommended-wrap');
          if (!e.shiftKey && window.sg.common.constants.KEY_CODE.TAB === e.keyCode) {
            e.preventDefault();
            utils.setFocusFirstFocusableEl(popupWrap.target[0]);
          }
        },
        showTooltip: (e) => {
          if (!this.isPc && e.type === 'focusin') {
            return;
          }
          const tooltipWrap = $q(e.target).closest('.info-tooltip-wrap, .warranty-tooltip-wrap, .recommended-tooltip-wrap');
          if (tooltipWrap.target.length
            && (!e.relatedTarget || !$q(e.relatedTarget).closest(tooltipWrap.target[0]).target.length)) {
            this._toggleTooltip(true, e.target);
          }
        },
        hideTooltip: (e) => {
          if (!this.isPc && e.type === 'focusout') {
            return;
          }
          const tooltipWrap = $q(e.target).closest('.info-tooltip-wrap, .warranty-tooltip-wrap, .recommended-tooltip-wrap');
          if (tooltipWrap.target.length
            && (!e.relatedTarget || !$q(e.relatedTarget).closest(tooltipWrap.target[0]).target.length)) {
            if (e.type === 'click') {
              requestAnimationFrame(() => {
                const tooltipButton = tooltipWrap.find('.info-tooltip-btn, .warranty-tooltip-btn');
                if (utils.getMobileOS() === 'ios') {
                  setTimeout(() => utils.setFocusFirstFocusableEl(tooltipButton.target[0]), 450);
                } else {
                  utils.setFocusFirstFocusableEl(tooltipButton.target[0]);
                }
              });
              this._toggleTooltip(false, e.target);
            } else {
              setTimeout(() => {
                const isFocusout = $q(document.activeElement).closest(tooltipWrap.target[0]).target.length === 0;
                if (isFocusout) {
                  this._toggleTooltip(false, e.target);
                }
              }, 50);
            }
          }
        },
        escKeydown: (e) => {
          if (e.type === 'keydown' && e.keyCode === 27) {
            this.els.el.find('.tooltip').target.forEach((el) => {
              if ($q(el).css('display') === '' || $q(el).css('display') === 'block') {
                this._toggleTooltip(false, el);
              }
            });
          }
        },
        closeRecommended: this._closeRecommended.bind(this),
        changeTab: this._changeTab.bind(this),
        toggleViewMore: this._toggleViewMore.bind(this),
      };
      this._bindEvents();
      this.adjustPriceWrapHeight();
    }
    _bindEvents() {
      this.els.el.find('.tooltip').target.forEach((el) => {
        this._toggleTooltip(false, el);
      });
      this.els.el.find('.cta-recommended').target.forEach((el) => {
        const $el = $q(el);
        const ariaText = $el.attr('aria-label') || '';
        const openText = $el.attr('data-i18n-opened') || 'opened';
        const closeText = $el.attr('data-i18n-closed') || 'closed';
        if (ariaText.indexOf(openText) < 0 && ariaText.indexOf(closeText) < 0) {
          this._toggleRecommendedStatus(false,el);
        }
      });
      this.els.el.off('click', this.handler.click).on('click', this.handler.click);
      this.els.el.off('keydown', this.handler.keydown).on('keydown', this.handler.keydown);
      this.els.el.off('mouseover', this.handler.showTooltip).on('mouseover', this.handler.showTooltip);
      this.els.el.off('mouseout', this.handler.hideTooltip).on('mouseout', this.handler.hideTooltip);
      this.els.el.off('focusin', this.handler.showTooltip).on('focusin', this.handler.showTooltip);
      this.els.el.off('focusout', this.handler.hideTooltip).on('focusout', this.handler.hideTooltip);
      this.els.window.off('keydown', this.handler.escKeydown).on('keydown', this.handler.escKeydown);
      this.els.window.off('resize', this.handler.resize).on('resize', this.handler.resize);
    }
    _unBindEvents() {
      this.els.el.off('click', this.handler.click);
      this.els.el.off('keydown', this.handler.keydown);
      this.els.el.off('mouseover', this.handler.showTooltip);
      this.els.el.off('mouseout', this.handler.hideTooltip);
      this.els.el.off('focusin', this.handler.showTooltip);
      this.els.el.off('focusout', this.handler.hideTooltip);
      this.els.window.off('keydown', this.handler.escKeydown);
      this.els.window.off('resize', this.handler.resize);
    }
    _reInit() {
      this._bindEvents();
    }
    _destroy() {
      this._unBindEvents();
    }
    _toggleTooltip(isShow, el) {
      const tooltipWrap = $q(el).closest('.info-tooltip-wrap, .warranty-tooltip-wrap, .recommended-tooltip-wrap');
      const tooltip = tooltipWrap.find('.tooltip');
      const tooltipButton = tooltipWrap.find('.info-tooltip-btn, .warranty-tooltip-btn');
      const openText = tooltipButton.attr('data-i18n-opened') || 'opened';
      const closeText = tooltipButton.attr('data-i18n-closed') || 'closed';
      let ariaText = tooltipButton.attr('aria-label') || '';
      if (ariaText.indexOf(openText) < 0 && ariaText.indexOf(closeText) < 0) {
        ariaText = `${ariaText} ${closeText}`;
      }
      if (isShow) {
        tooltip.css({ display: 'block' });
        tooltipButton.attr('aria-label', ariaText.replace(closeText, openText));
      } else {
        tooltip.css({ display: 'none' });
        tooltipButton.attr('aria-label', ariaText.replace(openText, closeText));
      }
    }
    _toggleRecommendedStatus(isShow, el) {
      const $target = $q(el);
      const openText = $target.attr('data-i18n-opened') || 'opened';
      const closeText = $target.attr('data-i18n-closed') || 'closed';
      let ariaText = $target.attr('aria-label') || '';
      if (ariaText.indexOf(openText) < 0 && ariaText.indexOf(closeText) < 0) {
        ariaText = `${ariaText} ${closeText}`;
      }
      if (isShow) {
        $target.attr('aria-label', ariaText.replace(closeText, openText));
      } else {
        $target.attr('aria-label', ariaText.replace(openText, closeText));
      }
    }
    _openRecommended(e) {
      const target = $q(e.target);
      const productItem = target.closest('.myd17-my-product-list-full__item');
      const recommendedOpenButton = productItem.find('.myd17-my-product-list-full__item-info-cta .cta-recommended');
      const recommendedWrap = productItem.find('.myd17-my-product-list-full__recommended-wrap');
      if (recommendedOpenButton.hasClass('cta--emphasis')) {
        return;
      }
      this._toggleRecommendedStatus(true, recommendedOpenButton.target[0]);
      productItem.siblings().target.forEach((el) => {
        if ($q(el).find('.cta-recommended').target.length) {
          this._closeRecommended({ target: el });
        }
      });
      if (recommendedWrap.find('.myd17-my-product-list-full__recommended-tab').target.length) {
        this._changeTab({ target: recommendedWrap.find('.myd17-my-product-list-full__recommended-tab > a').target[0] });
      } else {
        recommendedWrap.find('.myd17-my-product-list-full__recommended').eq(0).addClass('open');
      }
      recommendedWrap.show();
      recommendedOpenButton.addClass('cta--emphasis');
      recommendedOpenButton.removeClass('cta--black');
      if (!this.isPc) {
        utils.setMobileFocusLoop(recommendedWrap.target[0]);
        utils.hiddenScroll();
        requestAnimationFrame(() => {
          if (utils.getMobileOS() === 'ios') {
            setTimeout(() => utils.setFocusFirstFocusableEl(recommendedWrap.target[0]), 450);
          } else {
            utils.setFocusFirstFocusableEl(recommendedWrap.target[0]);
          }
        });
      }
      this.reInit(recommendedWrap.target[0]);
      window.sg.common.lazyLoad.setLazyLoad();
    }
    _closeRecommended(e) {
      const target = $q(e.target);
      const productItem = target.closest('.myd17-my-product-list-full__item');
      const recommendedOpenButton = productItem.find('.myd17-my-product-list-full__item-info-cta .cta-recommended');
      const recommendedWrap = productItem.find('.myd17-my-product-list-full__recommended-wrap');
      if (recommendedOpenButton.hasClass('cta--black')) {
        return;
      }
      this._toggleRecommendedStatus(false, recommendedOpenButton.target[0]);
      recommendedWrap.hide();
      recommendedWrap.find('.myd17-my-product-list-full__recommended').target.forEach((el) => {
        $q(el).removeClass('open');
      });
      recommendedOpenButton.removeClass('cta--emphasis');
      recommendedOpenButton.addClass('cta--black');
      if (this.els.document.find('body').css('position') === 'fixed') {
        recommendedWrap.find('.tooltip').target.forEach((el) => {
          this._toggleTooltip(false, el);
        });
        utils.removeMobileFocusLoop();
        utils.visibleScroll();
        recommendedOpenButton.focus();
        recommendedWrap.off('keydown', this.handler.popupKeydown);
        recommendedWrap.find('.recommended-close').off('keydown', this.handler.popupCloseKeydown);
      }
    }
    _changeTab(e) {
      const target = $q(e.target);
      const recommendedWrap = target.closest('.myd17-my-product-list-full__recommended-wrap');
      const recommended = recommendedWrap.find('.myd17-my-product-list-full__recommended');
      const contents = $q(recommended.target[target.index()]);
      target.siblings().removeClass('active');
      target.addClass('active');
      target.siblings().attr('aria-selected', false);
      target.attr('aria-selected', true);
      recommended.hide();
      recommended.removeClass('open');
      contents.show();
      contents.addClass('open');
      window.sg.common.lazyLoad.setLazyLoad();
      this.adjustPriceWrapHeight();
    }
    _toggleViewMore(e) {
      const target = $q(e.target);
      const viewMore = target.closest('.myd17-my-product-list-full__item-view-more');
      const productItem = target.closest('.myd17-my-product-list-full__item');
      const productItemInfo = productItem.find('.myd17-my-product-list-full__item-info');
      const viewMoreText = viewMore.find('.myd17-my-product-list-full__item-view-more-text');

      if (viewMore.hasClass('open')) {
        viewMore.removeClass('open');
        productItemInfo.addClass('close');
        viewMoreText.text(viewMore.find('button').attr('data-i18n-view-more'));
      } else {
        viewMore.addClass('open');
        productItemInfo.removeClass('close');
        viewMoreText.text(viewMore.find('button').attr('data-i18n-view-less'));
      }
    }
    toggleRecommended(el, isOpen) {
      isOpen = isOpen === undefined
        ? $q(el).closest('.myd17-my-product-list-full__recommended-wrap').css('display') === 'none' : isOpen;
      if (isOpen) {
        this._openRecommended({ target: el });
      } else {
        this._closeRecommended({ target: el });
      }
      this.adjustPriceWrapHeight();
    }
    adjustPriceWrapHeight() {
      this.els.el.find('.myd17-my-product-list-full__recommended-wrap').target.forEach((el) => {
        let maxHeight = 0;
        if ($q(el).css('display') === 'block') {
          const openTab = $q(el).find('.myd17-my-product-list-full__recommended.open');
          const priceBox = openTab.find('.myd17-my-product-list-full__recommended-price-box');
          
          if (this.isPc) {
            priceBox.target.forEach((el) => {
              $q(el).css({ height: '' });
              maxHeight = Math.max(maxHeight, el.offsetHeight);
            });
            priceBox.target.forEach((el) => {
              $q(el).css({ height: `${maxHeight}px` });
            });
          } else {
            let evenEl = '';
            priceBox.target.forEach((el, index) => {
              $q(el).css({ height: '' });
              if (index % 2 === 0) {
                evenEl = el;
              } else if (index % 2 === 1) {
                maxHeight = Math.max(el.offsetHeight, evenEl.offsetHeight);
                $q(el).css({ height: `${maxHeight}px` });
                $q(evenEl).css({ height: `${maxHeight}px` });
              }
            });
          }
          
          openTab.addClass('tabOpen');
          const scrollbar = this.getChild('.myd17-my-product-list-full__recommended.tabOpen');
          scrollbar.resize();
          openTab.removeClass('tabOpen');
        }
      });
    }
  }

  window.sg.components.registerClass('myProductListFull', MyProductListFull);

  const selector = {
    section: '.myd17-my-product-list-full',
  };
  class MyProductsListFull {
    constructor(element) {
      this.el = {
        window: $q(window),
        section: $q(element),
      };

      MyProductsListFull.instances.set(element, this);
      
      this.init();
    }

    init() {
      this.setFocus();
    }

    reInit() {
      this.init();
    }

    setFocus(index) {
      const buttons = document.querySelectorAll('.myd17-my-product-list-full__item > .close-btn');
      if(!isNaN(index) && buttons[index]) {
        const button = buttons[index];
        const rect = button.getBoundingClientRect();
        const offset = window.pageYOffset + rect.top - 40;

        button.focus();
        button.classList.add('focus-btn');
        
        window.scrollTo({
          top: offset,
          behavior: 'smooth',
        });
        button.addEventListener('blur', () => {
          button.classList.remove('focus-btn');
        });
      }
    }
  }

  function init() {
    $q(selector.section).target.forEach((element) => {
      if (!MyProductsListFull.instances.has(element)) {
        new MyProductsListFull(element);
      }
    });
  }

  function reInit() {
    $q(selector.section).target.forEach((element) => {
      if (MyProductsListFull.instances.has(element)) {
        MyProductsListFull.instances.get(element).reInit();
      } else {
        new MyProductsListFull(element);
      }
    });
  }

  function setFocus(index) {
    $q(selector.section).target.forEach((element) => {
      if (MyProductsListFull.instances.has(element)) {
        MyProductsListFull.instances.get(element).setFocus(index);
      }
    });
  }

  MyProductsListFull.instances = new WeakMap();
  
  window.sg.components.myProductList = {
    init,
    reInit,
    setFocus,
  };

  $q.ready(init);
})();


