(() => {
	class SharedUtils {
		constructor (){
			this.util = this.init();
		}

		init(){
			return {
				getProductIcon(modelCategory){
					let iconMap = {AIRCONDITIONER : 'retention-product-air-conditioner', CAMERA : 'retention-product-camera', DEVICES : 'retention-product-devices',
							GALAXYFILP : 'retention-product-galaxy-filp', GALAXYFOLD : 'retention-product-galaxy-fold', GENERALDISPLAY : 'retention-product-general-display',
							IOT : 'retention-product-iot', LAPTOP : 'retention-product-laptop', MICROWAVE : 'retention-product-microwave',
							OVEN : 'retention-product-oven', PHONE : 'retention-product-phone', REFRIGERATOR : 'retention-product-refrigerator',
							ROBOTVACUUM : 'retention-product-robot-vacuum', SMARTHOME : 'retention-product-smart-home', SOUNDBAR : 'retention-product-sound-bar',
							STORAGE : 'retention-product-storage', TABLET : 'retention-product-tablet', TV : 'retention-product-tv',
							WASHER : 'retention-product-washer', WEARABLEWATCH : 'retention-product-wearable-watc',
							TVACCESSORY : 'speaker', MONITOR : 'general-display', HOMEAUDIODEVICE : 'home-theater',
							AIRPURIFIER : 'air-purifier', VACUUMCLEANER : 'robot-vacuum-light', DISHWASHER : 'dish-washer-light',
							WATCH : 'wearable-watch-light', EARBUDS : 'headphone', COMPUTER : 'pc',
							NON : 'retention-product-non-product-image'};

					let imageType = JSON.parse(JSON.stringify(modelCategory));
						imageType = imageType.toUpperCase().replace("-", "").replace(/\s/gi, "");
				
					return (typeof iconMap[imageType])=='undefined' ? 'retention-product-non-product-image' : iconMap[imageType];
				},
				isNotEmpty( value ) {
					if( (typeof value !== "number" && value === "") || value === null || value === undefined || ( value !== null && typeof value === "object" && !Object.keys(value).length ) ){
						return false
					}else{
						return true
					}
				},
				isSameDay(target1, target2){
				  return target1.getFullYear() === target2.getFullYear() &&
					target1.getMonth() === target2.getMonth() &&
					target1.getDate()=== target2.getDate();
				},
				parseDate(dateStr){
					var y = dateStr.substr(0,4),
						m = dateStr.substr(4,2) - 1,
						d = dateStr.substr(6,2),
						H = '00',
						M = '00';

					if(dateStr.length > 8){
						H = dateStr.substr(8,2);
						M = dateStr.substr(10,2);

						if(parseInt(H) > 23) H = parseInt(H) % 24 || '00';
						if(parseInt(M) > 59) M = parseInt(M) % 60 || '00';
					}
					var D = new Date(y,m,d,H,M);
					return (D.getFullYear() == y && D.getMonth() == m && D.getDate() == d && D.getHours() == H && D.getMinutes() == M) ? D : 'invalid date';
				},
				formatAMPM(date){
					var hours = date.getHours();
					var minutes = date.getMinutes();
					var ampm = hours >= 12 ? 'PM' : 'AM';

						hours = hours % 12;
						hours = hours < 10 ? (hours == 0 ? '12' : '0'+hours) : hours;
						minutes = minutes < 10 ? '0'+minutes : minutes;

					var strTime = hours + ':' + minutes + ' ' + ampm;

					return strTime;
				}
			}
		}
	}

	window.sg.mysamsung.myproductv2 = window.sg.mysamsung.myproductv2 || {};
	window.sg.mysamsung.myproductv2.SharedUtils = SharedUtils;
})();


