								if(siteCode == 'vn') deviceItem.SC_Description = careDate != '' ? `${Granite.I18n.get('Valid until {0}', [careDate.format(dateFormat)], 'ux25')}` : '';
								deviceItem.samsungCare_nextBtn_DisplayOpt = "";
