	mysamsung.myproductv2.fn.bindSCCTA = function(){
		const $scCTA = $(".js-sc-next-btn");
		$scCTA.off("click");
		$scCTA.on("click", function(e){
			let _this = $(this);
			let saType = $(this).attr('data-sa-type') || '';
			let policy_id = $(this).attr('data-policy-id') || '';

			sharedObj.scDeviceName = _this.closest(".myd17-my-product-list-full-ux25__item-wrap").find(".myd17-my-product-list-full-ux25__item-info-device-name").text();

			/*
			sc+ detail popup
			
			[Different Account Popup] (타 계정 연결 Case)
			> window.sg.mysamsung.scpj.init("{policy_id }", false);
			
			[Add to Account Popup] (SA 미 연결 Case)
			> window.sg.mysamsung.scpj.init("{serialNumber}", true);

			그외 정상 Case
			> window.sg.mysamsung.scp.init("{policy_id }");

			26.01.19 >> 케이스 상관없이 window.sg.mysamsung.scp.init(['policy_id' : policy_id, 'saFlag' : saFlag]);
			*/

			let serialNo = $(this).attr('data-sc-serialno') || '';
			let scPopupData = window.sg.mysamsung.myproductv2.scPopupInfo[serialNo] || [];
			if(scPopupData) window.sg.mysamsung.scp.init(scPopupData);
		});

		const $scOutCTA = $(".js-sc-out-btn");
		$scOutCTA.off("click");
		$scOutCTA.on("click", function(e){
			let _this = $(this);
			let outLink = $("#mySamsungSCRegistURL").val() || "";

			if(window.location.hostname == 'hshopfront.samsung.com'){ // 26.03.19 de,it,pl uat url 추가
				if(siteCode == 'de')
					outLink = 'https://de.uat.scplus.co/de_de';
				else if(siteCode == 'it')
					outLink = 'https://it.uat.scplus.co/it_it';
				else if(siteCode == 'pl')
					outLink = 'https://pl.uat.scplus.co/pl_pl';
			}

			if(outLink) window.open(`${outLink}?cid=SCP_Mypage`); // 가입가능 > Stand-alone 페이지로 이동 //26.03.11 cid 파라미터 추가
		});
	}	

