	const popupInstance = popup.create(document.querySelector(".popup.repair-status-popup"));

	const dateFormat = "dd-MM-yyyy";

	const repairStatusHTML = `<strong class="repair-status__description">${Granite.I18n.get("Check the repair progress of your registered device.")}</strong>
                  <div class="repair-status__list" role="list">
                  </div>`;

	const noRepairStatusJHTML = `<p class="repair-status__description-text">${Granite.I18n.get("No repair history available.")}</p>`;

