(() => {
    const comp = window.sg.sdf.comp;
    class PO {
        constructor (){
            window.sg.mysamsung = window.sg.mysamsung || {};
            this.$componentWrapper = $(".myd24-crp-banner.myd24-crp-banner__onlytext");
        }

        init(){
            if(this.$componentWrapper.length > 0){

                this.resultObj = this.getResultObj();

                let tmpPath = location.pathname.replace(/\/\s*$/, '').replace(".html","").split("/");
		        let tmpPathName = tmpPath[tmpPath.length - 1];
                if(tmpPathName==='rewards' && this.resultObj.hasPO){
                    this.callGCRMAPI(this.resultObj);
                }else{
                    //this.callSegmentationAPI(this.resultObj);
                }
            }
        }

        getResultObj(){
            return {
				hasPO : $("#siteCode").val()==='it'||$("#siteCode").val()==='pe'||$("#siteCode").val()==='pl'||$("#siteCode").val()==='vn'||$("#siteCode").val()==='pt'||$("#siteCode").val()==='hu'||$("#siteCode").val()==='za'? true : false,  
				message : null,
				modelCode : null,
				modelName : null,
                cta : null,
                rewardsUseYn : $("#myd24_rewardsUseYn").val()==='Y'? true:false,
                rewardsTierType : $("#myd24_rewardsTierType").val(),
                hasRewardsTier : $("#myd24_rewardsTierType").val()==='global' || $("#myd24_rewardsTierType").val()==='europe',
                isMember : false,
                pageTrack : (digitalData.page.pageInfo.pageTrack || "").toLowerCase()
            }
        }

        callGCRMAPI(resultObj){
            const siteCode = $("#siteCode").val();
            let policyId = `C-${$("#countryCode").val()}-2509-000001`;

            if(siteCode==='pe'){
                policyId = `C-${$("#countryCode").val()}-2509-000005`;
            }else if(siteCode==='pt'){
                policyId = `C-${$("#countryCode").val()}-2509-000003`;
            }else if(siteCode==='pl'){
                policyId = `C-${$("#countryCode").val()}-2509-000002`;
            }else if(siteCode==='za'){
                policyId = `C-${$("#countryCode").val()}-2509-000002`;
            }else if(siteCode==='it'){
                policyId = `C-${$("#countryCode").val()}-2510-000001`;
            }

            $.ajax({
                url : `/aemapi/v6/mysamsung/point/convert.json/sap/bc/ZRWD1113?ncp=${Math.random()}`,
                type : "GET",
                dataType : "json",
                timeout : 20000,
                beforeSend : function(xhr) {
                    xhr.setRequestHeader("sg-site-code", siteCode);
                    xhr.setRequestHeader("policy-id", policyId);
                },
                success : function(res) {
                    if (res && res.statusCode === 200 && isNotEmpty(res.resultData) && isNotEmpty(res.resultData.apiResult)) {
                        const result = res.resultData.apiResult;
                        resultObj.gcrm = result;
                        if( !isNotEmpty(result.numberQty) || !isNotEmpty(result.pointRate) || result.numberQty===0 || result.pointRate===0 ){ 
                            return false;
                        } 
                        if(resultObj.rewardsUseYn && resultObj.hasRewardsTier){
                            window.sg.mysamsung.poBanner.callRewardsMembershipAPI(resultObj);
                        }else{
                           // window.sg.mysamsung.poBanner.setDrawInit(resultObj);
                        } 
                    }
                }
            });
        }

		callSegmentationAPI(resultObj){
            const MARKETING_NAME = ["TV", "Refrigerator", "Phone", "Washer", "Vacuum cleaner"];
            const siteCode = $("#siteCode").val();
            const ncpparam = Math.random();

            $.ajax({
                url : `/aemapi/v6/mysamsung/${siteCode}/scv/user/segmentation`,
                type : "GET",
                dataType : "json",
                crossDomain : true,
                data: {
                    "siteCode" : siteCode,
                    "ncp" : ncpparam
                },
                success : function(data) {
                    let dtmArr = "";
                    let tempObj = {};
                    if( data.statusCode === 200 && isNotEmpty(data.resultData) && isNotEmpty(data.resultData.result) && isNotEmpty(data.resultData.result.userSegmentation) ){
                        const userSegmentation = data.resultData.result.userSegmentation;
                        let uData = [];
                        let cData = [];
                        
						let upType = userSegmentation.filter((m) =>( m.indexOf('up|') > -1) );
						if(upType.length>0){
                            MARKETING_NAME.filter( (m) => { for(let t in upType){ if(upType[t].indexOf(m) > -1) return uData.push(upType[t]); }});
							resultObj.hasPO = true;
                            resultObj.offer = poOfferDtm(uData[0]);
							tempObj = uData[0];
						}

                        let crossType = userSegmentation.filter((m) =>( m.indexOf('cross|') > -1) );
                        if(crossType.length>0){
                            MARKETING_NAME.filter( (m) => { for(let t in crossType){ if(crossType[t].indexOf(m) > -1) return cData.push(crossType[t]); }});
                            if(!resultObj.hasPO){
                                resultObj.hasPO = true;
                                resultObj.offer = poOfferDtm(cData[0]);
                                tempObj = cData[0];
                            }
                        }

                        if(cData.length>0 ) dtmArr = uData.concat(cData);
                        else  dtmArr = uData;

                        let modelCode = "";
                        let modelName = "";
                        if(isNotEmpty(dtmArr) && dtmArr.length > 0){
                            $.each(dtmArr, function(index, m){
                                let comma = '';
                                if (index > 0) {
                                    comma = ',';
                                }
                                modelCode += comma + poModelCode(m);
                                modelName += comma + poModelName(m);
                            });
                        }

                        let pageInfo = "other";
                        if(location.pathname.indexOf("myrepair") > 0){
                            pageInfo = "my_repair";			
                        } else if (location.pathname.indexOf("myproducts") > 0) {
                            pageInfo = "myproduct_main";
                        }
                        
                        if(resultObj.hasPO){
                            if(isNotEmpty(modelCode)) resultObj.modelCode = modelCode;
                            if(isNotEmpty(modelName)) resultObj.modelName = modelName;
                            resultObj.message = window.sg.mysamsung.poMessage("myd24", tempObj);
                            resultObj.anla = poMessageDtm(tempObj);
                            resultObj.cta = Granite.I18n.get("Talk to us");
                            resultObj.click = `window.sg.mysamsung.crpPOP('${tempObj}', '${pageInfo}')`;
                        }
                    }
                    window.sg.mysamsung.poBanner.setDraw();
                }
            });
        }

        callRewardsMembershipAPI(resultObj){
            window.sg.mysamsung.rewards.callApi({
                apiPath : "/rewards-partner/v2/users/rtt_guid/check?ncp=" + Math.random(),
                success : function(resData) {
                    if (resData && resData.isMember) {
                        resultObj.isMember = resData.isMember;
                        window.sg.mysamsung.poBanner.callTier(resultObj);
                    }
                }
            });
        }

        callTier(resultObj) {
            const siteCode = $("#siteCode").val();
            $.ajax({
                url: "/aemapi/v6/mysamsung/rewards/tierinfo",
                type: "GET",
                data: {
                    "siteCode" : siteCode,
                    "ncp" : Math.random()
                },
                dataType: 'json',
            }).done(function (data) {
                if( isNotEmpty(data) && isNotEmpty(data.resultData) && isNotEmpty(data.resultData.apiResult) && isNotEmpty(data.resultData.apiResult.d) ){
                    if(isNotEmpty(data.resultData.apiResult.d.TierCode)){
                        resultObj.tierName = data.resultData.apiResult.d.TierName;
                        window.sg.mysamsung.poBanner.setDrawInit(resultObj, data.resultData.apiResult.d.TierCode);
                    }
                }
            });
        }

        setDrawInit(resultObj, tierCode){
            const component = window.sg.mysamsung.poBanner.$componentWrapper;
            const siteCode = $("#siteCode").val();

            let tierPoint=0;
            component.find("ul li").each(function(){
                if(2 === $(this).data("tierPointType") && tierCode === $(this).data("tierLevel")) {
                    if(!isNaN($(this).data("tierPoint"))) {
                        const defualtPoint = !isNaN($(this).data("defaultPoint")) ? parseFloat($(this).data("defaultPoint")) : 0;
                        tierPoint = parseFloat($(this).data("tierPoint")) + defualtPoint;
                    }
                }
            });

            if(tierPoint===0 && !isNotEmpty(tierCode)){
                tierPoint = 1;
            }

            resultObj.tierPoint = tierPoint;
            resultObj.dtmTagging = `earn a total of ${resultObj.tierPoint+resultObj.gcrm.pointRate}% rewards for your next purchase till [campaign end date]! (${resultObj.tierName.toLowerCase()} ${resultObj.tierPoint}% + extra ${resultObj.gcrm.pointRate}%)`;
            component.append(` 
                <div class="myd24-crp-banner__onlytext-wrap">
                    <h2 class="myd24-crp-banner__onlytext-headline">
                        ${Granite.I18n.get("Earn a total of {0}% rewards for your next purchase till [campaign end date]!", `<span>${resultObj.tierPoint+resultObj.gcrm.pointRate}</span>`)}
                        (${Granite.I18n.get(resultObj.tierName)} <span>${resultObj.tierPoint}</span>% + ${Granite.I18n.get("Extra")} <span>${resultObj.gcrm.pointRate}</span>%)
                    </h2>
                    <a class="myd24-crp-banner__onlytext-link" href="/${siteCode}/offer/ai-just-for-you/" role="button" aria-label="${Granite.I18n.get("Learn more")}. ${Granite.I18n.get("Open Chat")}"
                        an-tr="myd24_personalized offering banner-${resultObj.pageTrack}-link text-cta-content click" an-ca="content click" an-ac="feature" an-la="usp banner:${resultObj.dtmTagging}:learn more">${Granite.I18n.get("Learn more")}</a>
                </div>
            `);
        }

        setDraw(){
            const poBanner = window.sg.mysamsung.poBanner;
            const component = comp.dispatch(poBanner.$componentWrapper);
            const sliderTarget = $(".sdf-po").get(0);

			// 중복 append 방지
			sliderTarget.innerHTML = '';
			component.invokeTemplate("po", poBanner, sliderTarget);
            setTimeout(()=>{ 
                if(poBanner.resultObj.hasPO) _satellite.track("banner");
                else sliderTarget.remove();   
            },500);
          
            // MYD24 po banner cs Support 적용
            let poBannerArea = document.querySelector(".myd24-crp-banner__onlytext").cloneNode(true);
            if(poBannerArea && document.querySelector(".step-ui-wrap")){
                document.querySelector(".step-ui-wrap").insertBefore(poBannerArea, document.querySelector(".step-ui"));
                document.querySelector(".step-ui-wrap").querySelector(".myd24-crp-banner__onlytext").setAttribute("style", "display:none;");
            }
        }
    }
    
    function poOfferDtm(data){
        let txt = "";
        if( isNotEmpty(data) ){
            const poType = data.split("|")[0];
            const poPDType = data.split("|")[1].toLowerCase();
            const poPDName = data.split("|")[2].toLowerCase();
            const poPDModel = data.split("|").reverse()[0];
            const poRepair = data.split("|")[3] === 'repair' ? "yes" : "no"; 
            const poRewardP = data.split("|")[3].indexOf('rewards')>-1 ? "yes" : "";
            const poRewardsPTemp = data.split("|")[4]!==undefined && data.split("|")[4].indexOf('rewards')>-1 ? "yes" : "no";

            txt = `selling_${poType}:category_${poPDType}:model_${poPDName}:repair_${poRepair}:rewards_${poRewardP||poRewardsPTemp}:SKU_${poPDModel}`;
        }

        return txt;
    }

    function poMessageDtm(data) {
		let resultData = "";
		if( isNotEmpty(data) ){
			const po = data.split("|");					// segmentation API
			const isType = po[0].toLowerCase();			// up, cross
			const isCategory = po[1].toLowerCase(); 	// category
            const isMarketing = po[2].toLowerCase();    // marketing

			if(isType==='up'){
				if(isCategory==='phone'){
					resultData = `meet galaxy ai! switch your ${isMarketing} with your unique offer`;
				}else if(isCategory==='tv'){
					resultData = `Time for ${isMarketing} powered by AI: Your exclusive offers await`;
				}else if(isCategory==='refrigerator' || isCategory==='washer' || isCategory==='vacuum cleaner'){
					resultData = `Live smarter with a Bespoke AI ${isMarketing} using exclusive offers`;
				}
			}else{
				if(isCategory==='phone'){
					resultData = `Get the ultimate ${isMarketing} combo with your unique offer`;
				}else if(isCategory==='tv'){
					resultData = `Meet your ${isMarketing}'s perfect match with your unique offer`;
				}else if(isCategory==='washer' || isCategory==='vacuum cleaner'){
					resultData = `Explore your Bespoke AI ${isMarketing} dream team, your offer awaits`;
				}
			}
		}
		return resultData;
	}

	function poModelCode(data){
        return data.split("|").reverse()[0];
    }

    function poModelName(data){
        return data.split("|")[2];
    }

    function isNotEmpty( value ) {
        if( (typeof value !== "number" && value === "") || value === null || value === undefined || ( value !== null && typeof value === "object" && !Object.keys(value).length ) ){
            return false
        }else{
            return true
        }
    }

    const po = new PO();
    po.init();
	window.sg.mysamsung.poBanner = po;
})();
(() => {
  let csSupportContentsEl;
  const setFocusCenterAlign = () => {
    if (!csSupportContentsEl) {
      csSupportContentsEl = document.querySelector('.cs-support__contents');
    }

    if (csSupportContentsEl) {
      csSupportContentsEl.addEventListener('keyup', (e) => {
        if (window.sg.common.constants.KEY_CODE.TAB === e.keyCode) {
          const focusElTop = document.activeElement.getBoundingClientRect().top;
          const focusElCenter = document.activeElement.getBoundingClientRect().height / 2;
          const currentScrollY = (document.body.scrollTop || document.documentElement.scrollTop);
          const viewportCenter = window.innerHeight / 2;
          const targetPos = focusElTop + focusElCenter + currentScrollY - viewportCenter;

          window.scrollTo(0, targetPos);
        }
      });
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setFocusCenterAlign);
  } else {
    setFocusCenterAlign();
  }

  let resizingTimer;

  const resize = () => {
    if (!csSupportContentsEl) {
      csSupportContentsEl = document.querySelector('.cs-support__contents');
    }

    if (csSupportContentsEl) {
      if (!csSupportContentsEl.classList.contains('resizing')) {
        csSupportContentsEl.classList.add('resizing');
      }

      if (resizingTimer) {
        clearTimeout(resizingTimer);
      }

      resizingTimer = setTimeout(() => csSupportContentsEl.classList.remove('resizing'), 320);
    }
  };

  window.addEventListener('resize', resize);
})();

(() => {
  const $q = window.sg.common.$q;

  class CsSupportCta extends window.sg.components.Base {
    _init() {
      this.els = {
        section: $q(this.el),
        window: $q(window),
      };

      this.handler = {
        resize: () => {
          this.winH = window.sg.common.utils.getViewPort().height;
          this.els.dummy.css({ height: `${this.els.section.offset().height}px` });
          this._setFixed();
        },
        scroll: this._setFixed.bind(this),
      };

      this._setElements();
      this._bindEvents();
      this.handler.resize();
    }

    _reInit() {
      this._unBindEvents();

      this._setElements();
      this._bindEvents();
      this.handler.resize();
    }

    _update() {
      this.handler.resize();
    }

    _destroy() {
      this._unBindEvents();
    }

    _setElements() {
      this.els.parent = this.els.section.parent();
      this.els.dummy = this.els.parent.find('.cs-support-cta__dummy');
      this.winH = null;
    }

    _bindEvents() {
      this.els.window.off('resize',this.handler.resize).on('resize',this.handler.resize);
      this.els.window.off('scroll',this.handler.scroll).on('scroll',this.handler.scroll);
    }

    _unBindEvents() {
      this.els.window.off('resize',this.handler.resize);
      this.els.window.off('scroll',this.handler.scroll);
    }

    _setFixed(){
      const parentRect = this.els.parent.offset();
      const stepUiHeight = document.querySelector('.step-ui-wrap') ? document.querySelector('.step-ui-wrap').getBoundingClientRect().height : null;

      if(this.winH > parentRect.bottom){
        this.els.section.removeClass('cs-support-cta--fixed');
        this.els.section.addClass('cs-support-cta--absolute');
      }else if(this.winH - stepUiHeight > parentRect.top){
        this.els.section.addClass('cs-support-cta--fixed');
        this.els.section.removeClass('cs-support-cta--absolute');
      }else {
        this.els.section.removeClass('cs-support-cta--fixed');
        this.els.section.removeClass('cs-support-cta--absolute');
      }
    }
  }

  window.sg.components.registerClass('csSupportCta', CsSupportCta);
})();

(() => {
  const $q = window.sg.common.$q;

  class StepUI extends window.sg.components.Base {
    _init() {
      this.els = {
        section: $q(this.el),
        window: $q(window),
      };

      this.handler = {
        resize: () => {
          this._setFixed();
        },
        scroll: this._setFixed.bind(this),
      };

      this._setElements();
      this._bindEvents();
    }

    _reInit() {
      this._unBindEvents();

      this._setElements();
      this._bindEvents();
    }

    _update() {
      this.handler.resize();
    }

    _destroy() {
      this._unBindEvents();
    }

    _setElements() {
      this.els.tabBtn = this.els.section.find('.tab__item-title');
      this.els.parent = this.els.section.parent();
      this.els.dummy = this.els.parent.find('.step-ui__dummy');
    }

    _bindEvents() {
      this.els.window.off('resize',this.handler.resize).on('resize',this.handler.resize);
      this.els.window.off('scroll',this.handler.scroll).on('scroll',this.handler.scroll);
    }

    _unBindEvents() {
      this.els.window.off('resize',this.handler.resize);
      this.els.window.off('scroll',this.handler.scroll);
    }

    _setFixed(){
      const isFixed = this.els.section.hasClass('step-ui--fixed');
      const targetRect = (isFixed ? this.els.dummy : this.els.section).offset();
      const parentRect = this.els.parent.offset();

      if(targetRect.height > parentRect.bottom){
        this.els.section.removeClass('step-ui--fixed');
        this.els.section.addClass('step-ui--absolute');
      }else if(parentRect.top < 0){
        this.els.section.addClass('step-ui--fixed');
        this.els.section.removeClass('step-ui--absolute');
      }else {
        this.els.section.removeClass('step-ui--fixed');
        this.els.section.removeClass('step-ui--absolute');
      }
    }
  }

  window.sg.components.registerClass('stepUI', StepUI);
})();

(() => {
  class FileUpload extends window.sg.components.Base {
    _init() {
      this.els = {
        el: this.el,
        inputEl: null,
        nameEl: null,
        formatEl: null,
        errorTextEls: null,
      };

      this._setElements();
      this._bindEvents();
    }

    _setElements() {
      this.els.inputEl = this.els.el.querySelector('.file-upload__input');
      this.els.nameEl = this.els.el.querySelector('.file-upload__name');
      this.els.formatEl = this.els.el.querySelector('.file-upload__format');
      this.els.errorTextEls = this.els.el.querySelectorAll('.file-upload__text__error');
    }

    _bindEvents() {
      this._setInputState = this._setInputState.bind(this);

      this.els.inputEl.addEventListener('change', this._setInputState);
      this.els.inputEl.addEventListener('focus', this._setInputState);
      this.els.inputEl.addEventListener('blur', this._setInputState);
    }

    _unBindEvents() {
      this.els.inputEl.removeEventListener('change', this._setInputState);
      this.els.inputEl.removeEventListener('focus', this._setInputState);
      this.els.inputEl.removeEventListener('blur', this._setInputState);
    }

    _reInit() {
      this._unBindEvents();
      this._setElements();
      this._bindEvents();
    }

    _destroy() {
      this._unBindEvents();
    }

    _setInputState(e) {
      const file = this.els.inputEl.files[0];

      if (file) {
        const fileNameArr = file.name.split('.');
        const fileformat = `.${fileNameArr[fileNameArr.length - 1]}`;
        let fileName = '';
        
        fileNameArr.forEach((text, index) => {
          if (index < fileNameArr.length - 1) {
            fileName += `${text}.`;
          } else {
            fileName = fileName.slice(0, -1);
          }
        });

        this.els.el.classList.add('active');
        this.els.nameEl.textContent = fileName.trim();
        this.els.formatEl.textContent = fileformat;

        if (e && e.type === 'change') {
          this.setState('normal');
        }
      } else {
        this.els.el.classList.remove('active');
        this.els.nameEl.textContent = '';
        this.els.formatEl.textContent = '';
      }

      if (document.activeElement === this.els.inputEl) {
        this.els.el.classList.add('focus');
      } else {
        this.els.el.classList.remove('focus');
      }
      
      if (e && e.type === 'change') {
        this.emit('fileSelect');
      }
    }

    setState(state, errorId) {
      let id = '';
      let errorTextId = '';
      let errorTextTarget = '';

      if (this.els.inputEl.getAttribute('aria-describedby')) {
        id = this.els.inputEl.getAttribute('aria-describedby');
      }

      this.els.errorTextEls.forEach((el) => {
        el.style.display = 'none';
      });

      if (this.els.errorTextEls.length) {
        if (errorId) {
          errorTextTarget = this.els.el.querySelector(errorId);
        } else if (this.els.errorTextEls[0] && this.els.errorTextEls[0].id) {
          errorTextTarget = this.els.errorTextEls[0];
        }
      }

      if (errorTextTarget) {
        errorTextId = errorTextTarget.id;
      }

      this.els.errorTextEls.forEach((el) => {
        id = id.replace(el.id, '').trim();
      });

      this.els.el.classList.remove('error', 'disabled');
      !id ? this.els.inputEl.removeAttribute('aria-describedby') 
        : this.els.inputEl.setAttribute('aria-describedby', id);

      switch (state) {
      case 'error':
        id = `${errorTextId} ${id}`;
        id = id.trim();

        this.els.el.classList.add('error');
        id ? this.els.inputEl.setAttribute('aria-describedby', id)
          : this.els.inputEl.removeAttribute('aria-describedby');

        if (errorTextTarget) {
          errorTextTarget.style.display = 'block';
        }
        break;
      case 'disable':
        this.els.el.classList.add('disabled');
        this.els.inputEl.setAttribute('disabled', '');
        break;
      default:
        this.els.inputEl.removeAttribute('disabled');
      }
    }

    getFiles() {
      return this.els.inputEl.files;
    }

    clear() {
      if (this.els.inputEl) {
        this.els.inputEl.value = '';
        this.setState('normal');
        this._setInputState();
      }
    }
  }

  window.sg.components.registerClass('fileUpload', FileUpload);
  window.sg.common.fileUpload = {
    setState: (el, state) => {
      FileUpload.create(el).setState(state);
    },
    getFiles: (el) => FileUpload.create(el).getFiles(),
    clear: (el) => FileUpload.create(el).clear(),
  };
})();

(() => {
  const $q = window.sg.common.$q;

  class MultiFileUpload extends window.sg.components.Base {
    _init() {
      this.els = {
        el: $q(this.el),
        fileUploadWrap: null,
        fileUploadInput: null,
        fileUploadList: null,
        errorTextList: null,
      };
      this.fileReg;
      this.limitSize;
      this.limitLength;
      this.fileUploadComp;
      
      this.handler = {
        click: (e) => {
          const target = $q(e.target);

          if (target.closest('.file-upload__input').target.length) {
            this.els.fileUploadInput.target[0].value = '';
            this.fileUploadComp.setState('nomal');
          }

          if (target.closest('.multi-file-upload__list-cta').target.length) {
            const item = target.closest('.multi-file-upload__list-item');
            const nextElement = $q(item.target[0].nextElementSibling);
            const prevElement = $q(item.target[0].previousElementSibling);
            item.removeClass('is-show');
            item.find('.file-name').text('');
            item.find('.file-format').text('');
            this.els.fileUploadList.append(item.target[0]);
            
            if (nextElement.hasClass('is-show')) {
              nextElement.find('.multi-file-upload__list-cta').focus();
            } else if(prevElement.hasClass('is-show')) {
              prevElement.find('.multi-file-upload__list-cta').focus();
            } else {
              this.els.fileUploadInput.focus();
              this.els.fileUploadList.hide();
            }
          }
        },

        fileSelect: (e) => {
          const target = $q(e.target).find('.file-upload__input');
          const fileUploadListItem = this.els.fileUploadList.find('.multi-file-upload__list-item.is-show');
          
          if (target.target[0].files[0]) {
            const file = target.target[0].files[0];
            
            if (fileUploadListItem.target.length >= this.limitLength && this.limitLength) {
              this.fileUploadComp.setState('error', '#error-text-max-file-count');
              return;
            }

            if (!file.type.match(this.fileReg)) {
              this.fileUploadComp.setState('error', '#error-text-file-format');
              return;
            }

            if (file.size > this.limitSize && this.limitSize) {
              this.fileUploadComp.setState('error', '#error-text-max-file-size');
              return;
            }

            this.fileUploadComp.setState('disable');
            this.emit('fileSelect');
          } else {
            this.fileUploadComp.setState('nomal');
          }
        },
      };
      
      this._setElements();
      this._bindEvents();
      this.els.el.find('.file-upload__text__assistive').attr('aria-hidden', false);
    }

    _setElements() {
      this.els.fileUploadWrap = this.els.el.find('.file-upload');
      this.els.fileUploadValue = this.els.el.find('.file-upload__input__value');
      this.els.fileUploadInput = this.els.fileUploadWrap.find('.file-upload__input');
      this.els.fileUploadList = this.els.el.find('.multi-file-upload__list');
      this.els.errorTextList = this.els.el.find('.file-upload__text__error');
      this.fileReg = new RegExp(`(${this.els.fileUploadInput.attr('accept').replaceAll(',', '|')})`, 'i');
      this.limitSize = (1024 * 1024) * this.els.fileUploadInput.target[0].dataset.maxFileSize || 0;
      this.limitLength = this.els.fileUploadInput.target[0].dataset.maxFileCount || 0;
      this.fileUploadComp = this.getChild(this.els.fileUploadWrap.target[0]);
    }

    _bindEvents() {
      this.els.el.off('click', this.handler.click).on('click', this.handler.click);
      this.els.fileUploadWrap.off('fileSelect', this.handler.fileSelect).on('fileSelect', this.handler.fileSelect);
    }

    _unBindEvents() {
      this.els.el.off('click', this.handler.click);
      this.els.fileUploadWrap.off('fileSelect', this.handler.fileSelect);
    }

    _reInit() {
      this._unBindEvents();
      this._setElements();
      this._bindEvents();
    }

    _destroy() {
      this._unBindEvents();
    }

    setFileUploaded(index) {
      const fileNameArr = this.els.fileUploadValue.target[0].innerText.split('.');
      const fileformat = `.${fileNameArr[fileNameArr.length - 1]}`;
      const fileItem = this.els.fileUploadList.find('.multi-file-upload__list-item').eq(this.limitLength - 1);
      let fileName = '';
      this.els.fileUploadValue.target[0].innerText.split('.').forEach((text, index) => {
        if (index < fileNameArr.length - 1) {
          fileName += text;
        }
      });

      if (this.els.fileUploadList.css('display') === 'none') {
        this.els.fileUploadList.show();
      }

      fileItem.find('.file-name').text(fileName);
      fileItem.find('.file-format').text(fileformat);
      fileItem.addClass('is-show');
      this.els.fileUploadList.prepend(fileItem.target[0]);
      this.fileUploadComp.setState('nomal');
      
      if (index) {
        fileItem.target[0].dataset.idx = index;
      }
    }
  }
  
  window.sg.components.registerClass('multiFileUpload', MultiFileUpload);
})();

(() => {
  const upArrowSvg = `<svg viewBox="0 0 96 96" id="close-up-bold" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
                        <path d="M78.65 65.254L47.999 34.145l-30.65 31.109-5.699-5.615 36.349-36.892L84.35 59.639z"/></svg>`;
  const downArrowSvg = `<svg viewBox="0 0 96 96" id="open-down-bold" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
                          <path d="M48 73.254L11.651 36.361l5.698-5.614L48 61.855l30.651-31.108 5.698 5.614z"/></svg>`;
  const prevArrowSvg = `<svg viewBox="0 0 96 96" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
                          <path d="M60.243 84.389l-38.019-36.39 38.019-36.388 5.532 5.779-31.981 30.609 31.981 30.612z"/></svg>`;
  const nextArrowSvg = `<svg viewBox="0 0 96 96" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true">
                         <path d="M35.757 84.389l-5.533-5.778 31.982-30.612L30.224 17.39l5.533-5.779 38.018 36.388z"/></svg>`;

  const { KEY_CODE } = window.sg.common.constants;
  const { closest, getCurrentMediaType } = window.sg.common.utils;

  class DateTimePicker extends window.sg.components.Base {
    _init() {
      this.els = {
        el: this.el,
        inputEl: null,
        mobileInputEl: null,
        pickerEl: null,
        pickerDaysEl: null,
        pickerMonthEl: null,
        errorTextEl: null,
      };

      this.type = null;
      this.picker = null;
      this.lang = '';
      this.i18n = {
        today: 'Today',
        selected: 'Selected',
        prevMonth: 'Previous month',
        nextMonth: 'Next month',
      };

      this.dateFormat = 'd-m-Y';
      this.datePattern = '(0[1-9]|1\\d|2\\d|3[01])-(0[1-9]|1[0-2])-(19|20\\d{2})';
      this.timePattern = '([01][0-9]|2[0-3]):([0-5][0-9])';
      this.inputValue = '';

      this._setElements();
      this._bindEvents();
    }

    _setElements() {
      this.els.inputEl = this.els.el.querySelector('.datetime-picker__input');
      this.els.errorTextEl = this.els.el.querySelector('.datetime-picker__text__error');
      this.type = this.els.el.getAttribute('data-type');
      const today = this.els.el.getAttribute('data-i18n-today');
      this.i18n.today = today ? today : this.i18n.today;
      const selected = this.els.el.getAttribute('data-i18n-selected');
      this.i18n.selected = selected ? selected : this.i18n.selected;
      const prevMonth = this.els.el.getAttribute('data-i18n-prev-month');
      this.i18n.prevMonth = prevMonth ? prevMonth : this.i18n.prevMonth;
      const nextMonth = this.els.el.getAttribute('data-i18n-next-month');
      this.i18n.nextMonth = nextMonth ? nextMonth : this.i18n.nextMonth;
      this._setPicker();
    }

    _bindEvents() {
      this._setInputState = this._setInputState.bind(this);
      this._handleInput = this._handleInput.bind(this);
      this._handlePickerKeydown = this._handlePickerKeydown.bind(this);
      this._handlePickerKeyup = this._handlePickerKeyup.bind(this);
      this._handlePickerClick = this._handlePickerClick.bind(this);
      this._handleDatePickerKeydown = this._handleDatePickerKeydown.bind(this);
      this._handleDatePickerInputClick = this._handleDatePickerInputClick.bind(this);

      if (!this.picker.isMobile) {
        this.els.inputEl.addEventListener('change', this._setInputState);
        this.els.inputEl.addEventListener('focus', this._setInputState);
        this.els.inputEl.addEventListener('blur', this._setInputState);
        this.els.inputEl.addEventListener('input', this._handleInput);
        this.els.pickerEl.addEventListener('keydown', this._handlePickerKeydown);
        this.els.pickerEl.addEventListener('keyup', this._handlePickerKeyup);
        this.els.pickerEl.addEventListener('click', this._handlePickerClick);

        if (this.type === 'date' && this.els.pickerMonthEl && this.els.pickerDaysEl) {
          this.els.pickerMonthEl.addEventListener('keydown', this._handleDatePickerKeydown);
          this.els.pickerDaysEl.addEventListener('keydown', this._handleDatePickerKeydown);
          this.els.inputEl.addEventListener('click', this._handleDatePickerInputClick);
        }
      } else {
        this.els.mobileInputEl.addEventListener('change', this._setInputState);
        this.els.mobileInputEl.addEventListener('focus', this._setInputState);
        this.els.mobileInputEl.addEventListener('blur', this._setInputState);
      }
    }

    _unBindEvents() {
      if (!this.picker.isMobile) {
        this.els.inputEl.removeEventListener('change', this._setInputState);
        this.els.inputEl.removeEventListener('focus', this._setInputState);
        this.els.inputEl.removeEventListener('blur', this._setInputState);
        this.els.inputEl.removeEventListener('input', this._handleInput);
        this.els.pickerEl.removeEventListener('keydown', this._handlePickerKeydown);
        this.els.pickerEl.removeEventListener('keyup', this._handlePickerKeyup);
        this.els.pickerEl.removeEventListener('click', this._handlePickerClick);

        if (this.type === 'date' && this.els.pickerMonthEl && this.els.pickerDaysEl) {
          this.els.pickerMonthEl.removeEventListener('keydown', this._handleDatePickerKeydown);
          this.els.pickerDaysEl.removeEventListener('keydown', this._handleDatePickerKeydown);
          this.els.inputEl.removeEventListener('click', this._handleDatePickerInputClick);
        }
      } else {
        this.els.mobileInputEl.removeEventListener('change', this._setInputState);
        this.els.mobileInputEl.removeEventListener('focus', this._setInputState);
        this.els.mobileInputEl.removeEventListener('blur', this._setInputState);
      }
    }

    _reInit() {
      this._unBindEvents();

      const calendarFocused = (this.picker.calendarContainer && this.picker.calendarContainer.contains(document.activeElement)) || this.els.inputEl === document.activeElement;
      const calendarOpend = this.els.el.classList.contains('open');

      this.picker.destroy();
      if(calendarOpend && this.els.el.classList.contains('type-v2')){
        this.els.el.classList.remove('open');
      }

      this._setElements();
      this._bindEvents();

      if(this.els.el.classList.contains('type-v2') && calendarFocused){
        this.els.inputEl.focus();
        if(!calendarOpend){
          this.picker.close();
        }
      }
    }

    _destroy() {
      this._unBindEvents();
      this.picker.destroy();
    }

    _setDayEls() {
      if (this.picker.isMobile) {
        return;
      }

      const dayEls = this.picker.days.querySelectorAll('.flatpickr-day');
      const year = this.picker.currentYear;

      Array.from(dayEls).forEach((dayEl) => {
        const day = dayEl.textContent;
        let month = this._getMonth();

        if (dayEl.classList.contains('prevMonthDay')) {
          month = this._getMonth(-1);
        } else if (dayEl.classList.contains('nextMonthDay')) {
          month = this._getMonth(1);
        }

        dayEl.setAttribute('data-year', year);
        dayEl.setAttribute('data-month', month);
        dayEl.setAttribute('data-day', day);

        const date = new Date(year, month, day);
        // const dayOfWeek = this.picker.l10n.weekdays.longhand[date.getDay()];

        // formatDate
        // dayEl.setAttribute('aria-label', `${dayOfWeek} ${dayEl.getAttribute('aria-label')}`);
        dayEl.setAttribute('aria-label', `${this.picker.formatDate(date, 'j, F Y, l')}`);

        if (dayEl.classList.contains('today')) {
          const label = dayEl.getAttribute('aria-label');

          if (label.indexOf(this.i18n.today) < 0) {
            dayEl.setAttribute('aria-label', `${dayEl.getAttribute('aria-label')}, ${this.i18n.today}`);
          }
        }

        if (dayEl.classList.contains('selected')) {
          const label = dayEl.getAttribute('aria-label');

          if (label.indexOf(this.i18n.selected) < 0) {
            dayEl.setAttribute('aria-label', `${dayEl.getAttribute('aria-label')}, ${this.i18n.selected}`);
          }
        }
      });

      setTimeout(() => {
        const calendarNotFocus = this.picker.calendarContainer.contains(document.activeElement) === false;
        const canChangeFocusMove = this.picker.nextMonthNav.disabled !== this.picker.prevMonthNav.disabled;
        if(calendarNotFocus && canChangeFocusMove){
          (this.picker.nextMonthNav.disabled ? this.picker.prevMonthNav : this.picker.nextMonthNav).focus();
        }
      },40);
    }

    _getMonth(delta = 0) {
      let currentMonth = this.picker.currentMonth;
      currentMonth += delta;
      return (currentMonth + 12) % 12;
    }

    _handleDatePickerKeydown(e) {
      if (this.picker.days.contains(e.target)) {
        if (e.keyCode === KEY_CODE.RIGHT || e.keyCode === KEY_CODE.LEFT
          || e.keyCode === KEY_CODE.UP || e.keyCode === KEY_CODE.DOWN) {
          e.preventDefault();
          e.stopPropagation();

          if (e.ctrlKey) {
            const year = this.picker.currentYear;

            if (e.keyCode === KEY_CODE.RIGHT) {
              this.picker.changeMonth(1);
            } else if (e.keyCode === KEY_CODE.LEFT) {
              this.picker.changeMonth(-1);
            } else if (e.keyCode === KEY_CODE.UP) {
              this.picker.changeYear(year + 1);
            } else if (e.keyCode === KEY_CODE.DOWN) {
              this.picker.changeYear(year - 1);
            }

            this._setDayElFocus();
          } else {
            let day = parseInt(e.target.getAttribute('data-day'));
            let month = this._getMonth();
            const daysInMonth = this.picker.utils.getDaysInMonth(this.picker.currentMonth);
            let nextDay;
            let monthDelta = 0;

            if (e.keyCode === KEY_CODE.RIGHT) {
              nextDay = day + 1;
            } else if (e.keyCode === KEY_CODE.LEFT) {
              nextDay = day - 1;
            } else if (e.keyCode === KEY_CODE.UP) {
              nextDay = day - 7;
            } else if (e.keyCode === KEY_CODE.DOWN) {
              nextDay = day + 7;
            }

            if (nextDay < 1) {
              monthDelta = -1;
              month = this._getMonth(monthDelta);
              const daysInMonth = this.picker.utils.getDaysInMonth(month);
              day = daysInMonth + nextDay;
            } else if (nextDay > daysInMonth) {
              monthDelta = 1;
              month = this._getMonth(monthDelta);
              day = nextDay - daysInMonth;
            } else {
              day = nextDay;
            }

            const year = this.picker.currentMonth + monthDelta > 11 ? this.picker.currentYear + 1 :
              this.picker.currentMonth + monthDelta < 0 ? this.picker.currentYear - 1 : this.picker.currentYear;

            const date = new Date(year, month, day);
            let minDate;
            let maxDate;

            if (this.picker.config.minDate) {
              minDate = new Date(this.picker.config.minDate);
            }

            if (this.picker.config.maxDate) {
              maxDate = new Date(this.picker.config.maxDate);
            }

            if ((!minDate || date >= minDate) && (!maxDate || date <= maxDate)) {
              monthDelta !== 0 ? this.picker.changeMonth(monthDelta) : null;
              const dayEl = this.picker.days.querySelector(`[data-year="${year}"][data-month="${month}"][data-day="${day}"]`);

              if (dayEl && !dayEl.classList.contains('flatpickr-disabled')) {
                dayEl.focus();
              }
            }
          }
        } else if (e.keyCode === KEY_CODE.TAB) {
          e.preventDefault();
          e.stopPropagation();

          const monthEls = [this.picker.prevMonthNav, this.picker.nextMonthNav];
          const setMonthElFocus = (els) => {
            for (let i = 0; i < els.length; i++) {
              if (!els[i].disabled) {
                els[i].focus();
                return;
              }
            }
          };

          if (!e.shiftKey) {
            setMonthElFocus(monthEls);
          } else {
            setMonthElFocus(monthEls.reverse());
          }
        }
      } else if (closest(e.target, '.flatpickr-prev-month') || closest(e.target, '.flatpickr-next-month')) {
        if (e.keyCode === KEY_CODE.RIGHT || e.keyCode === KEY_CODE.LEFT
          || e.keyCode === KEY_CODE.UP || e.keyCode === KEY_CODE.DOWN) {
          e.stopPropagation();
        } else if (e.keyCode === KEY_CODE.TAB) {
          e.stopPropagation();

          if ((!e.shiftKey && (closest(e.target, '.flatpickr-next-month') || this.picker.nextMonthNav.disabled)) ||
            (e.shiftKey && (closest(e.target, '.flatpickr-prev-month') || this.picker.prevMonthNav.disabled))) {
            e.preventDefault();
            this._setDayElFocus();
          }
        } else if (e.keyCode === KEY_CODE.ENTER) {
          let date;
          let minDate;
          let maxDate;

          if (this.picker.config.minDate) {
            minDate = new Date(this.picker.config.minDate);
          }

          if (this.picker.config.maxDate) {
            maxDate = new Date(this.picker.config.maxDate);
          }

          if (closest(e.target, '.flatpickr-prev-month')) {
            date = new Date(this.picker.currentYear, this.picker.currentMonth - 1, 1);

            if (minDate && date <= minDate) {
              requestAnimationFrame(() => this.picker.nextMonthNav.focus());
            }
          } else if (closest(e.target, '.flatpickr-next-month')) {
            date = new Date(this.picker.currentYear, this.picker.currentMonth + 2, 0);

            if (maxDate && date >= maxDate) {
              requestAnimationFrame(() => this.picker.prevMonthNav.focus());
            }
          }
        }
      } else if (closest(e.target, '.flatpickr-current-month')) {
        if (e.keyCode === KEY_CODE.RIGHT || e.keyCode === KEY_CODE.LEFT
          || e.keyCode === KEY_CODE.UP || e.keyCode === KEY_CODE.DOWN) {
          const yearInputEl = this.els.pickerMonthEl.querySelector('.numInput.cur-year');

          if (yearInputEl && yearInputEl.readOnly) {
            e.preventDefault();
            e.stopPropagation();
          }
        }
      }
    }

    _setDayElFocus() {
      const dayEl = this.picker.days.querySelector('.flatpickr-day.selected:not(.flatpickr-disabled):not(.prevMonthDay):not(.nextMonthDay)')
        || this.picker.days.querySelector('.flatpickr-day.today:not(.flatpickr-disabled):not(.prevMonthDay):not(.nextMonthDay)')
        || this.picker.days.querySelector('.flatpickr-day:not(.flatpickr-disabled):not(.prevMonthDay):not(.nextMonthDay)');

      if (dayEl) {
        dayEl.focus();
      }
    }

    _handleInput(e) {
      const value = e.target.value;

      if (value.replace(/^\s+$/, '') === '') {
        return;
      }

      const pattern = this.type === 'date' ? new RegExp(this.datePattern) : new RegExp(this.timePattern);
      const match = value.match(pattern);

      if (match) {
        e.target.value = match[0];
      } else {
        if (this.inputValue.replace(/^\s+$/, '') !== '' && this.inputValue.match(pattern)) {
          e.target.value = this.inputValue;
        }
      }

      this.inputValue = e.target.value;
    }

    _handlePickerReady() {
      if (this.type === 'date') {
        const yearInputEl = this.els.el.querySelector('.numInput.cur-year');

        if (yearInputEl && !yearInputEl.disabled) {
          yearInputEl.disabled = true;
        }

        const prevMonthEl = this.els.el.querySelector('.flatpickr-prev-month');
        if (prevMonthEl) {
          prevMonthEl.setAttribute('aria-label', this.i18n.prevMonth);
        }

        const nextMonthEl = this.els.el.querySelector('.flatpickr-next-month');
        if (nextMonthEl) {
          nextMonthEl.setAttribute('aria-label', this.i18n.nextMonth);
        }
      } else if (this.type === 'time') {
        const upArrowEls = this.els.el.querySelectorAll('span.arrowUp');
        const downArrowEls = this.els.el.querySelectorAll('span.arrowDown');

        Array.from(upArrowEls).forEach((el) => {
          el.insertAdjacentHTML('afterbegin', upArrowSvg);
        });

        Array.from(downArrowEls).forEach((el) => {
          el.insertAdjacentHTML('afterbegin', downArrowSvg);
        });

        const hourInputEl = this.els.el.querySelector('.flatpickr-hour');
        const minInputEl = this.els.el.querySelector('.flatpickr-minute');

        if (hourInputEl && minInputEl) {
          hourInputEl.insertAdjacentHTML('afterend', '<span class="outline"></span>');
          minInputEl.insertAdjacentHTML('afterend', '<span class="outline"></span>');
        }
      }
    }

    _handlePickerOpen() {
      this.els.el.classList.add('open');

      const height = this._getCurrentPixelSize(this.type === 'date' ? '360' : '42');
      const inputEl = this._getCurrentInputEl();
      const rect = inputEl.getBoundingClientRect();

      if (window.innerHeight - rect.bottom < height && rect.top > height) {
        this.els.pickerEl.style.top = 'auto';
        this.els.pickerEl.style.bottom = '100%';
      } else {
        this.els.pickerEl.style.top = '100%';
        this.els.pickerEl.style.bottom = 'auto';
      }

      if (this.type === 'date') {
        if (this.validate() === 0) {
          const date = this.picker.parseDate(inputEl.value, this.dateFormat);
          if(!this.picker.selectedDates.find((selectedDate) => selectedDate.getTime() === date.getTime())) {
            this.picker.setDate(date);
          }
        }

        requestAnimationFrame(() => {
          this._setDayEls();
          this._setDayElFocus();
        });
      }
    }

    _handlePickerClose() {
      this.els.el.classList.remove('open');

      requestAnimationFrame(() => {
        this._setInputState();
        this.emit('pickerPopupClose');
      });
    }

    _handlePickerKeydown(e) {
      if (e.keyCode === KEY_CODE.TAB) {
        if (!e.shiftKey) {
          if (closest(e.target, '.flatpickr-am-pm')) {
            requestAnimationFrame(() => {
              const el = this.els.pickerEl.querySelector('.flatpickr-hour');
              if (el) {
                el.focus();
              }
            });
          }
        } else {
          if (closest(e.target, '.flatpickr-hour')) {
            requestAnimationFrame(() => {
              const el = this.els.pickerEl.querySelector('.flatpickr-am-pm');
              if (el) {
                el.focus();
              }
            });
          }
        }
      } else if (e.keyCode === KEY_CODE.ESC) {
        requestAnimationFrame(() => {
          this.picker.close();
        });
      }
    }

    _handlePickerKeyup(e) {
      if (e.keyCode === KEY_CODE.TAB) {
        e.stopPropagation();
      }
    }

    _handlePickerClick(e) {
      if (this.type === 'time' && (closest(e.target, '.arrowUp') || closest(e.target, '.arrowDown'))) {
        const numInputWrapperEl = closest(e.target, '.numInputWrapper');

        if (numInputWrapperEl) {
          const inputEl = numInputWrapperEl.querySelector('input');

          if (inputEl) {
            inputEl.focus();
          }
        }
      }
    }

    _handleDatePickerInputClick(e) {
      requestAnimationFrame(() => {
        if (document.activeElement === e.target) {
          this._setDayElFocus();
        }
      });
    }

    _getCurrentInputEl() {
      return !this.picker.isMobile ? this.els.inputEl : this.els.mobileInputEl;
    }

    _setInputState(e = null) {
      const inputEl = this._getCurrentInputEl();
      const value = inputEl.value;

      if (value.replace(/^\s+$/, '') !== '') {
        this.els.el.classList.add('active');

        if (e && e.type === 'change') {
          this.setState('normal');
        }
      } else {
        this.els.el.classList.remove('active');
      }


      if (document.activeElement === inputEl) {
        this.els.el.classList.add('focus');
      } else {
        this.els.el.classList.remove('focus');
      }

      if (this.els.el.querySelector('.datetime-picker__input__date-wrap')) {
        this.els.el.querySelector('span.datetime-picker__input__date').innerText = this.picker.formatDate(this.picker.selectedDates[0] || new Date(), this.dateFormat);
      }

      if(this.picker.isMobile && e && e.type === 'blur'){
        this.emit('pickerPopupClose');
      }
    }

    _getLang() {
      const lang = document.documentElement.lang;
      if (lang) {
        const langCode = lang.substring(0, 2);

        if (langCode !== 'en') {
          return langCode;
        }
      }
    }

    _setPicker() {
      this._handlePickerReady = this._handlePickerReady.bind(this);
      this._handlePickerOpen = this._handlePickerOpen.bind(this);
      this._handlePickerClose = this._handlePickerClose.bind(this);
      this._setDayEls = this._setDayEls.bind(this);
      this.lang = this._getLang();

      if (this.type === 'date') {
        this._setDatePicker();
      } else if (this.type === 'time') {
        this._setTimePicker();
      }

      if (!this.picker.isMobile) {
        this.els.pickerEl = this.els.el.querySelector('.flatpickr-calendar');

        if (this.type === 'date') {
          this.els.pickerMonthEl = this.els.pickerEl.querySelector('.flatpickr-months');
          this.els.pickerDaysEl = this.els.pickerEl.querySelector('.flatpickr-days');
        }

        this.els.inputEl.removeAttribute('readonly');
      } else {
        this.els.mobileInputEl = this.els.el.querySelector('.flatpickr-mobile');

        if (this.els.inputEl.id || this.els.inputEl.dataset.id) {
          const id = this.els.inputEl.id || this.els.inputEl.dataset.id;
          this.els.mobileInputEl.id = id;
          this.els.inputEl.dataset.id = id;
          this.els.inputEl.removeAttribute('id');
        }
      }
    }

    _setDatePicker() {
      const minDate = this.els.el.getAttribute('data-min-date');
      const maxDate = this.els.el.getAttribute('data-max-date');
      const useMobile = this.els.el.getAttribute('data-use-mobile') === 'true' || false;

      const options = {
        monthSelectorType: 'static',
        static: true,
        prevArrow: prevArrowSvg,
        nextArrow: nextArrowSvg,
        onReady: this._handlePickerReady,
        onOpen: this._handlePickerOpen,
        onClose: this._handlePickerClose,
        onChange: this._setDayEls,
        onMonthChange: this._setDayEls,
        onYearChange: this._setDayEls,
        dateFormat: this.dateFormat,
        disableMobile: useMobile,
      };

      if (minDate) {
        options.minDate = minDate;
      }

      if (maxDate) {
        options.maxDate = maxDate;
      } 

      if (this.lang) {
        options.locale = this.lang;
      }

      if (this.els.inputEl) {
        // eslint-disable-next-line no-undef
        this.picker = flatpickr(this.els.inputEl, options);
      }
    }

    _setTimePicker() {
      const minTime = this.els.el.getAttribute('data-min-time');
      const maxTime = this.els.el.getAttribute('data-max-time');
      const useMobile = this.els.el.getAttribute('data-use-mobile') === 'true' || false;

      const options = {
        static: true,
        enableTime: true,
        noCalendar: true,
        dateFormat: 'H:i',
        onReady: this._handlePickerReady,
        onOpen: this._handlePickerOpen,
        onClose: this._handlePickerClose,
        disableMobile: useMobile,
      };

      if (minTime) {
        options.minTime = minTime;
      }

      if (maxTime) {
        options.maxTime = maxTime;
      }

      if (this.els.inputEl) {
        // eslint-disable-next-line no-undef
        this.picker = flatpickr(this.els.inputEl, options);
      }
    }

    _getCurrentPixelSize(pixel) {
      const mediaType = getCurrentMediaType();
      const size = parseFloat(pixel);
      const isConvert = mediaType !== 'desktop-over';
      const resolution = mediaType.indexOf('mobile') > -1 ? 360 : 1440;

      if (!isNaN(size)) {
        return !isConvert ? pixel : parseFloat((pixel / resolution * window.innerWidth).toFixed(3));
      }
    }

    setState(state) {
      const id = this.els.errorTextEl ? this.els.errorTextEl.id : '';
      const inputEl = this._getCurrentInputEl();

      switch (state) {
      case 'error':
        this.els.el.classList.add('error');
        id ? inputEl.setAttribute('aria-describedby', id)
          : inputEl.removeAttribute('aria-describedby');
        break;
      default:
        this.els.el.classList.remove('error');
        inputEl.removeAttribute('aria-describedby');
      }
    }

    getValue() {
      if (this.type === 'date' && this.picker.selectedDates.length) {
        return this.picker.formatDate(this.picker.selectedDates[0], this.dateFormat);
      } else {
        return this._getCurrentInputEl().value;
      }
    }

    setValue(dateValue) {
      if (this.type === 'date') {
        this.picker.setDate(dateValue);
        this._setInputState();
      }
    }

    validate() {
      const inputEl = this._getCurrentInputEl();
      const value = inputEl.value;

      if (value.replace(/^\s+$/, '') === '') {
        return 1;
      }

      const datePattern = new RegExp(`^${this.datePattern}$`);
      const timePattern = new RegExp(`^${this.timePattern}$`);

      if (this.type === 'date') {
        const match = value.match(datePattern);

        if (match) {
          const date = new Date(Number(match[3]), Number(match[2]) - 1, Number(match[1]));
          let minDate;
          let maxDate;

          if (this.picker.config.minDate) {
            minDate = new Date(this.picker.config.minDate);
          }

          if (this.picker.config.maxDate) {
            maxDate = new Date(this.picker.config.maxDate);
          }

          if ((minDate && date < minDate) || (maxDate && date > maxDate)) {
            return 3;
          }
        } else {
          return 2;
        }
      } else {
        const match = value.match(timePattern);

        if (match) {
          const time = new Date();
          time.setHours(Number(match[1]), Number(match[2]));

          let minTime;
          let maxTime;

          if (this.picker.config.minTime) {
            const time = new Date(this.picker.config.minTime);
            const hour = time.getHours();
            const minute = time.getMinutes();

            minTime = new Date();
            minTime.setHours(hour, minute);
          }

          if (this.picker.config.maxTime) {
            const time = new Date(this.picker.config.maxTime);
            const hour = time.getHours();
            const minute = time.getMinutes();

            maxTime = new Date();
            maxTime.setHours(hour, minute);
          }

          if ((minTime && time < minTime) || (maxTime && time > maxTime)) {
            return 3;
          }
        } else {
          return 2;
        }
      }

      return 0;
    }

    clear() {
      if (this.picker) {
        this.picker.clear();
        this.setState('normal');
        this._setInputState();
      }
    }
  }

  window.sg.components.registerClass('dateTimePicker', DateTimePicker);
  window.sg.common.dateTimePicker = {
    setState: (el, state) => {
      DateTimePicker.create(el).setState(state);
    },
    getValue: (el) => DateTimePicker.create(el).getValue(),
    setValue: (el, dateValue) => DateTimePicker.create(el).setValue(dateValue),
    validate: (el) => DateTimePicker.create(el).validate(),
    clear: (el) => DateTimePicker.create(el).clear(),
  };
})();

