(() => {
  const $q = window.sg.common.$q;
  const utils = window.sg.common.utils;
  const lazyLoad = window.sg.common.lazyLoad;

  class RequestACallConfirmation extends window.sg.components.Base {
    _init() {
      this.els = {
        el: $q(this.el),
        window: $q(window),
        togglebtn: null,
      };
      this._setElements();
      this._bindEvents();
      window.sg.common.icon.update(this.els.el.target[0]);
      lazyLoad.setLazyLoad();
    }

    _setElements() {
      this.els.togglebtn = this.els.el.find('.requst-a-call-confirmation__product-info-head-cta');
    }

    _bindEvents() {
      this._toggleAccordion = this._toggleAccordion.bind(this);
      // this.els.togglebtn.addEventListener('click', this._toggleAccordion);
      [...document.querySelectorAll('.requst-a-call-confirmation__product-info-head-cta')].forEach((el) => {
        el.addEventListener('click', this._toggleAccordion);
      });
    }

    _unBindEvents() {
      [...document.querySelectorAll('.requst-a-call-confirmation__product-info-head-cta')].forEach((el) => {
        el.removeEventListener('click', this._toggleAccordion);
      });
    }

    _reInit() {
      this._unBindEvents();
      this._setElements();
      this._bindEvents();
    }

    _destroy() {
      this._unBindEvents();
    }
    
    _toggleAccordion(el) {
      const listItem = el.currentTarget.closest('.requst-a-call-confirmation__product-info-wrap');
      const itemBtn = listItem.querySelector('.requst-a-call-confirmation__product-info-head-cta');
      const isOpen = listItem.classList.contains('is-open');
      const listContent = listItem.querySelector('.requst-a-call-confirmation__product-info-list');
      const hiddenText = itemBtn.querySelector('span.hidden');
      const globalText = {
        Expand: 'Click to Expand',
        Collapse: 'Click to Collapse',
      };

      setTimeout(() => {
        if (utils.getCurrentDevice() === 'mobile') {
          if (!isOpen) {
            listItem.classList.add('is-open');
            itemBtn.setAttribute('aria-expanded', true);
            listContent.setAttribute('aria-hidden', false);
            hiddenText.textContent = globalText.Collapse;
          } else {
            listItem.classList.remove('is-open');
            itemBtn.setAttribute('aria-expanded', false);
            listContent.setAttribute('aria-hidden', true);
            hiddenText.textContent = globalText.Expand;
          }
        }
      }, 0);
    }
  }

  window.sg.components.registerClass('requestACallConfirmation', RequestACallConfirmation);
})();

