            resultObj.step.state = (siteCode==='my'||siteCode==='id')?e.currentTarget.getAttribute("data-isocodeShort"):e.currentTarget.getAttribute("data-state");
            resultObj.step.stateView = e.currentTarget.getAttribute("data-state");
