            if(selectEl.querySelector("#shipping-provider-text-label span")!==null){
                resultObj.step.shipping = selectEl.querySelector("#shipping-provider-text-label span").innerText;
                resultObj.step.shipMethod = selectEl.querySelector("#shipping-provider-text-label span").dataset.shipmethod;
            }
            validCheckNext();
