    function callTICKET_DETAIL(){
        let bodyData = {
            "Input": {
              "Bukrs": resultObj.IvCompany,
              "Langu": resultObj.IvLangu,
              "TrNo": new URLSearchParams(location.search).get('trNo') || "",
              "BpNo": repairSupport.csInfo.partner || ""
            },
            "IvSystem": "",
            "IvLogin": "X",
            "Return": {
                "EvKey" : ""
            }
        };

        repairSupport.callYourServiceAPI(`siteCode=${siteCode}&apiType=I&apiId=ZIF_PS_TICKET_DETAIL&apiPath=${resultObj.ysIpaasApiPrefixPath}_zgw_ps_ticket_detail/1.0/ImportSet&ncp=${Math.random()}`, bodyData, true, function(data) {
            if( mailIn.isNotEmpty(data.resultData) && mailIn.isNotEmpty(data.resultData.result) && mailIn.isNotEmpty(data.resultData.result.d) && mailIn.isNotEmpty(data.resultData.result.d.Return) && mailIn.isNotEmpty(data.resultData.result.d.Return.Output) ){
                resultObj.paidPrice = parseFloat(data.resultData.result.d.Return.Output.RepairPrice);
                ticketNumberContainer(data.resultData.result.d.Return.Output.TrNo);
                productInfoContainer(data.resultData.result.d.Return.Output);
                estimatedQuoteContainer();
                mailIn.showDraw(".mail-in-confirmation__inner");
            }
        },function(jqXHR, textStatus, errorThrown) {
            window.sg.mysamsung.openDynamicAlertPopup(Granite.I18n.get("There was a problem loading this page. Please try again in a few minutes."), repairSupport.errorPopupCtaAttrs, null, null, resultObj.dtmErrorPopup.anTr, resultObj.dtmErrorPopup.case1, function(){
            });
        });
    }

    function printParcelLabelCTA(){
        let bodyData = {
            "IvCompany": resultObj.IvCompany,
            "IvObjectId": mailIn.isNotEmpty(resultObj.step.EvObjectId) ? resultObj.step.EvObjectId : new URLSearchParams(location.search).get('trNo') || "",
            "Return": {
              "EvUrl": "",
              "EvRetCode": "",
              "EvRetMsg": ""
            }
        };

        let labelUrl = `siteCode=${siteCode}&apiType=I&apiId=ZIF_PS_GET_LABEL_URL&apiPath=${resultObj.ysIpaasApiPrefixPath}_zgw_ps_get_label_url/1.0/ImportSet&ncp=${Math.random()}`;
        if(siteCode==='au'){
            labelUrl = `siteCode=${siteCode}&apiType=I&apiId=GCIC_CAP_AP_SC_GET_PS_BARCODE&apiPath=gcic_cap_ap_sc_get_ps_barcode/1.0/ImportSet&ncp=${Math.random()}`;
        }
        repairSupport.callYourServiceAPI(labelUrl, bodyData, true, function(data) {
            if( mailIn.isNotEmpty(data.resultData) && mailIn.isNotEmpty(data.resultData.result) && mailIn.isNotEmpty(data.resultData.result.d) && mailIn.isNotEmpty(data.resultData.result.d.Return) ){
                if(mailIn.isNotEmpty(data.resultData.result.d.Return.EvRetCode) && data.resultData.result.d.Return.EvRetCode!=='S'){
                    ERROR_productPrintCTA = true;
                }
                
                if(!ERROR_productPrintCTA && mailIn.isNotEmpty(data.resultData.result.d.Return.EvUrl)) {
                    mailIn.findDraw(confirm, productPrint).html(`
                        <button class="cta cta--outlined cta--black" type="button" onclick="window.open('${data.resultData.result.d.Return.EvUrl}')" aria-label="${Granite.I18n.get("Parcel label")}"
                                an-tr="${resultObj.taggingPrefix}-step cta"
                                an-ca="account"
                                an-ac="my device"
                                an-la="get support:confirmation:parcel label">${Granite.I18n.get("Parcel label")}
                        </button>
                    `);
                }
            }
        },function(jqXHR, textStatus, errorThrown) {
            window.sg.mysamsung.openDynamicAlertPopup(Granite.I18n.get("Due to a system error, the shipment label creation has failed. Please try again after a few minutes, and if the issue persists, contact the logistics company with your tracking number. We apologize for any inconvenience."), repairSupport.errorPopupCtaAttrs, null, null, resultObj.dtmErrorPopup.anTr, resultObj.dtmErrorPopup.case3, function(){
                ERROR_productPrintCTA = true;
            });
        });
    }

    function estimatedQuoteContainer(){
        const searchParams = new URLSearchParams(location.search);
        const stepParam = searchParams.get('step');

        let quoteHeadline = Granite.I18n.get("Estimated quote");
        let paymentDetailCTA = `<button class="cta cta--contained cta--black" aria-label="${Granite.I18n.get("Insert payment details")}"
                                    an-tr="${resultObj.taggingPrefix}-step cta"
                                    an-ca="account"
                                    an-ac="my device"
                                    an-la="get support:pre-authorized payment:insert payment details">${Granite.I18n.get("Insert payment details")}
                                </button>`;
        let quoteDescription = `<p class="mail-in-confirmation__product-estimated-quote-description">
                                    ${Granite.I18n.get("Please complete payment before sending your device for repairs, as the payment is valid for 24 hours.")}
                                </p>`;
        document.querySelector(cancelCTA).style.display = "block";
        if(stepParam==='co'){
            quoteHeadline = Granite.I18n.get("Payment completed");
            paymentDetailCTA = "";
            quoteDescription = "";
            document.querySelector(cancelCTA).style.display = "none";
        }

        if(resultObj.isDpD2d){
            quoteHeadline = Granite.I18n.get("Estimated repair cost");
            paymentDetailCTA = "";
            quoteDescription = "";
            document.querySelector(cancelCTA).style.display = "none";
        } 
        mailIn.findDraw(confirm, estimatedQuote).html(`
            <strong class="mail-in-confirmation__product-estimated-quote-headline">${quoteHeadline}</strong>
            <span class="mail-in-confirmation__product-estimated-quote-price">${currencyComma(resultObj.paidPrice, resultObj.priceCurrency).replace("VND","₫")}</span>
            <p class="mail-in-confirmation__product-estimated-quote-gst">${Granite.I18n.get("Including GST")}</p>
            ${paymentDetailCTA}   
            ${quoteDescription}
        `);

        mailIn.gridDraw(".mail-in-confirmation__product-estimated-quote"); 
    }

    function mySupportRequestContainer(data){
        const symptomView = mailIn.isNotEmpty(resultObj.step.symptom) ? resultObj.step.symptom : data.Category1; 

        let detailedSymptom = "";
        if( mailIn.isNotEmpty(resultObj.step.detailedSymptom) || (mailIn.isNotEmpty(data) && mailIn.isNotEmpty(data.Category2) )){
            const detailedSymptomView = mailIn.isNotEmpty(resultObj.step.detailedSymptom) ? resultObj.step.detailedSymptom : data.Category2;
            detailedSymptom = `<li class="mail-in-confirmation__product-request-item" role="listitem">${Granite.I18n.get("Detailed symptom")}: ${detailedSymptomView}</li>`;
        }

        let comment = "";
        if( mailIn.isNotEmpty(resultObj.step.comment) || (mailIn.isNotEmpty(data) && mailIn.isNotEmpty(data.Comments) )){
            const commentView = mailIn.isNotEmpty(resultObj.step.comment) ? resultObj.step.comment : data.Comments;
            comment = `<li class="mail-in-confirmation__product-request-item" role="listitem">${Granite.I18n.get("Description")}: ${commentView}</li>`;
        }

        let viewDraw = `
            <strong class="mail-in-confirmation__product-request-title">${Granite.I18n.get("My support request")}</strong>
            <ul class="mail-in-confirmation__product-request-list" role="list">
                <li class="mail-in-confirmation__product-request-item" role="listitem">${symptomView}</li>
                ${detailedSymptom}
                ${comment}
            </ul>
        `;

        return viewDraw;
    }

