    function serviceAppCase(){
        const searchParams = new URLSearchParams(location.search);
        const appViewParam = searchParams.get('appView') || window.sessionStorage.getItem("appView");
        const sourceParam = searchParams.get('source');
        if( appViewParam==='SM'||appViewParam==='SA'||appViewParam==='ST' ){
            if( mailIn.isNotEmpty(sourceParam) ){
                window.location.href = "voc://view/twaClose";
            }else {     // source 파라미터가 없으면 (멤버스앱 자가진단, Payment 단계를 안거친 경우)
                if( appViewParam==='SM' ){
                    window.location.href = "voc://view/twaClose";
                }else if( appViewParam==='ST' ){
                    window.location.href = "scapp://webview.close";
                }else{
                    window.location.href = "intent:#Intent;action=android.settings.SETTINGS;end";
                }
            }
        }
    }

    function moveConfirmation() {
        if(resultObj.paidRepair && !resultObj.isDpD2d){
            document.querySelector("#component-area .cs-support-v2__header-headline").innerHTML = Granite.I18n.get("Pre-authorized payment");
            document.querySelector(myRepairCTA).setAttribute("an-la", "get support:pre-authorized payment:my repair");
            mailIn.hideDraw(".mail-in-confirmation__product-print-invoice");
            mailIn.showDraw(".mail-in-confirmation__product-estimated-quote button");
        }else{ 
            document.querySelector("#component-area .cs-support-v2__header-headline").innerHTML = Granite.I18n.get("Confirmation");
            mailIn.gridDraw(".mail-in-confirmation__product-print-invoice");
            mailIn.showDraw(".mail-in-confirmation__product-reservation");
            mailIn.hideDraw(".mail-in-confirmation__product-estimated-quote button");
        }

        if(resultObj.ajaxFinalCalled.hasStep5){
            setEvent();
            getMeasures();
            // YS 페이지 Re-direction
            if(resultObj.paidRepair===undefined && !resultObj.isDpD2d) printParcelLabelCTA();
            if(repairSupport.modelInfo.stepParam==='co'){
                callTICKET_DETAIL();
            }else{
                ticketNumberContainer();
                infoContainer();
            }
        }

        const searchParams = new URLSearchParams(location.search);
        let appViewParam = searchParams.get('appView') || window.sessionStorage.getItem("appView");
        if( appViewParam==='SM'||appViewParam==='SA'||appViewParam==='ST' ){
            document.querySelector(completeCTA).style.display = "flex";
        }
    }

