	const regExpCheck = /[\{\}\[\]\/?.,;:|\)*~`!^\-_+<>@\#$%&\\\=\(\'\"]/g;

	repairSupport.inhome = repairSupport.inhome || {};
	repairSupport.inhome.step = 'symptom';
	repairSupport.inhome.symptomText = '';
	repairSupport.inhome.purchaseDate = '';
