	repairSupport.inhome.uploadFileCheckFlag = false;
	repairSupport.inhome.purchaseDateCheckFlag = false;
	repairSupport.inhome.checkValidateFlag = false;
	repairSupport.inhome.symptomIssueCheckFlag = false;
	repairSupport.inhome.monthCheckFlag = false;
