	repairSupport.inhome.yearInputCheckFlag = false;

	let dateFormat = "dd-MM-yyyy";
	if(isRtl()){ dateFormat = "yyyy-MM-dd"; }

	function isNotEmpty( value ) {
		if( (typeof value !== "number" && value === "") || value === null || value === undefined || ( value !== null && typeof value === "object" && !Object.keys(value).length ) ){
			return false
		}else{
			return true
		}
	}

	function compareDate(target1, target2){
		return target1.getFullYear() === target2.getFullYear() &&
			target1.getMonth() === target2.getMonth() &&
			target1.getDate()=== target2.getDate();
	}

	function byteCount(str) {
		let count = 0;
		for(let i = 0; i < str.length; i++) {
			let charCode = str.charCodeAt(i);
			if (charCode <= 0x7f) {
				count += 1;
			}else if(charCode <= 0x7ff) {
				count += 2;
			}else if(charCode <= 0xffff) {
				count += 3;
			}else{
				count += 4;
			}
		}
		return count;
	}

