			if(_this.value === null || _this.value === ''){
				repairSupport.inhome.symptomIssueCheckFlag = false;
				window.sg.common.textFieldv2.setState(document.querySelector('.in-home-symptom__comment .text-field-v2'), 'error');

				$(".in-home-symptom__comment .text-field-v2__text.error").html('');
			}
